  document.getElementById("totalQty").innerText = qty(totalQty);
  document.getElementById("totalValue").innerText = money(totalValue);

  const noteBox = document.getElementById("noteBox");
  if (h.note) {
    noteBox.style.display = "block";
    noteBox.innerText = `Note: ${h.note}`;
  } else {
    noteBox.style.display = "none";
  }

  await setQr(h);
  bindPrintButton();
}

appsmith.onReady(() => {
  render(appsmith.model || {});
  bindPrintButton();
});

appsmith.onModelChange((model) => {
  render(model || {});
});
